      uniform float uBend;
      uniform vec3 uBendCenter;
      varying float vDist;
      invariant gl_Position;
      void main() {
        vec4 wp = modelMatrix * vec4(position, 1.0);
        vec2 dxz = wp.xz - uBendCenter.xz;
        wp.y += uBend * dot(dxz, dxz);
        vec4 mv = viewMatrix * wp;
        vDist = length(mv.xyz);
        gl_Position = projectionMatrix * mv;
      }

